    96|async function ensureValidSession(): Promise<string | null> {
    97|  try {
    98|    const { data: { session } } = await supabase.auth.getSession();
    99|
   100|    if (session?.access_token) {
   101|      const expiresAt = session.expires_at ? session.expires_at * 1000 : 0;
   102|      const isExpiringSoon = expiresAt > 0 && (expiresAt - Date.now()) < 120000;
   103|
   104|      if (isExpiringSoon && session.refresh_token) {
   105|        console.log('[LandingDeploy] Token expiring soon — refreshing...');
   106|        const { data: refreshed, error: refreshErr } = await supabase.auth.refreshSession();
   107|        if (refreshed?.session?.access_token) {
   108|          console.log('[LandingDeploy] Session refreshed successfully');
   109|          return refreshed.session.access_token;
   110|        }
   111|        console.log('[LandingDeploy] Refresh failed, using current token:', refreshErr?.message);
   112|      }
   113|      return session.access_token;
   114|    }
   115|
   116|    console.log('[LandingDeploy] No active session — attempting refresh...');
   117|    const { data: refreshed } = await supabase.auth.refreshSession();
   118|    if (refreshed?.session?.access_token) {
   119|      console.log('[LandingDeploy] Recovered session via refresh');
   120|      return refreshed.session.access_token;
   121|    }
   122|
   123|    console.log('[LandingDeploy] No session recoverable');
   124|    return null;
   125|  } catch (err) {
   126|    console.log('[LandingDeploy] Session check error:', (err as Error)?.message);
