   131|async function verifyDeployAccess(): Promise<{ allowed: boolean; token: string | null; userId?: string | null; role?: string | null; reason?: string }> {
   132|  const token = await ensureValidSession();
   133|  if (!token) {
   134|    return {
   135|      allowed: false,
   136|      token: null,
   137|      userId: null,
   138|      role: null,
