   368|function normalizeGitHubRepositoryValue(value: string): string {
   369|  const trimmedValue = value.trim();
   370|  if (!trimmedValue) {
   371|    return '';
   372|  }
   373|
   374|  if (!trimmedValue.includes('github.com/')) {
   375|    return trimmedValue.replace(/\.git$/i, '');
   376|  }
   377|
   378|  try {
   379|    const parsed = new URL(trimmedValue);
   380|    return parsed.pathname.replace(/^\/+/, '').replace(/\.git$/i, '');
   381|  } catch {
   382|    return trimmedValue
   383|      .replace(/^https?:\/\/github\.com\//i, '')
   384|      .replace(/^git@github\.com:/i, '')
   385|      .replace(/\.git$/i, '')
   386|      .replace(/^\/+/, '');
   387|  }
