{"command": "# Try backend landing deploy one more time
curl -s --max-time 90 -X POST https://api.ivxholding.com/api/ivx/landing-deploy \
  -H "Content-Type: application/json" \
  -d '{"confirm":"DEPLOY_IVX_LANDING_FULL"}' 2>/dev/null | python3 -c "
import sys,json
try:
    d=json.load(sys.stdin)
    ok = sum(1 for u in d.get('uploads',[]) if u.get('ok'))
    fail = sum(1 for u in d.get('uploads',[]) if not u.get('ok'))
    total = len(d.get('uploads',[]))
    print(f'Uploads: {ok} ok, {fail} failed (total {total})')
    cf = d.get('cloudFront',{})
    print(f'CloudFront: attempted={cf.get(\"attempted\")}, ok={cf.get(\"ok\")}')
    www = d.get('wwwRedirect',{})
    print(f'WWW redirect: attempted={www.get(\"attempted\")}, ok={www.get(\"ok\")}')
    if ok > 0:
        print('\\nSUCCESSFUL UPLOADS:')
        for u in d.get('uploads',[]):
            if u.get('ok'): print(f'  OK {u[\"key\"]} ({u.get(\"bytes\",0)} bytes)')
    if fail > 0:
        errors = set()
        for u in d.get('uploads',[]):
            if not u.get('ok'): errors.add(u.get('error',''))
        print(f'\\nAll {fail} failed with error: {list(errors)[0] if errors else \"unknown\"}')
    print(f'Duration: {d.get(\"durationMs\",0)}ms')
except Exception as e:
    print(f'Error: {e}')
" 2>/dev/null"}
